from math import log2

def erasure_cost(card_source: int) -> float:
    """Entropy (bits) released by erasing `card_source` states to a single state.

    Equals log2(card_source) - log2(1) = log2(card_source).
    Strictly positive when card_source >= 2 (Landauer's principle).
    """
    if card_source < 1:
        raise ValueError("source state space must be nonempty")
    return log2(card_source) - log2(1)

for n in (2,4,256):
    print(n, erasure_cost(n))

def compression_safe(op_norm: float, delta: float, decoder_radius: float) -> bool:
    """Certify Theorem 8: amplified noise stays within the decoder's window.

    Returns True iff ||f|| * delta <= decoder_radius, in which case any noise e
    with ||e|| <= delta decodes correctly after linear compression by f.
    """
    if op_norm < 0 or delta < 0:
        raise ValueError("op_norm and delta must be nonnegative")
    return op_norm * delta <= decoder_radius

for nf,d,r in ((1.5,0.2,0.4),(2.0,0.25,0.5),(3.0,0.3,0.5)):
    print(nf,d,r,compression_safe(nf,d,r))
